import ImageKit from 'imagekit'
import type { SupabaseClient } from '@supabase/supabase-js'

/**
 * ImageKit server client.
 *
 * This module is server-only: it reads `IMAGEKIT_PRIVATE_KEY` and must never be
 * imported from a `'use client'` module. The browser only receives the short
 * lived upload signature generated by `getImageKitAuthParams`.
 */
export function getImageKitClient(): ImageKit {
  const publicKey = process.env.NEXT_PUBLIC_IMAGEKIT_PUBLIC_KEY
  const privateKey = process.env.IMAGEKIT_PRIVATE_KEY
  const urlEndpoint = process.env.NEXT_PUBLIC_IMAGEKIT_URL_ENDPOINT

  if (!publicKey || !privateKey || !urlEndpoint) {
    throw new Error(
      '[imagekit] Faltan las variables de entorno de ImageKit (NEXT_PUBLIC_IMAGEKIT_PUBLIC_KEY, IMAGEKIT_PRIVATE_KEY, NEXT_PUBLIC_IMAGEKIT_URL_ENDPOINT).',
    )
  }

  return new ImageKit({ publicKey, privateKey, urlEndpoint })
}

/**
 * Short lived upload credentials for direct browser uploads.
 * The private key never leaves the server: only the signature travels.
 */
export function getImageKitAuthParams(): {
  token: string
  expire: number
  signature: string
} {
  const { token, expire, signature } =
    getImageKitClient().getAuthenticationParameters()

  return { token, expire, signature }
}

/**
 * Deletes an uploaded file from ImageKit.
 * Callers must handle the rejection: a failed cleanup must not break a save.
 */
export async function deleteImageKitFile(fileId: string): Promise<void> {
  await getImageKitClient().deleteFile(fileId)
}

/**
 * Reads the ImageKit file id currently linked to a record.
 * A failed read returns null so the cleanup never blocks a save.
 */
export async function getPreviousImageKitFileId(
  supabase: SupabaseClient<any>,
  table: 'servicios' | 'mascotas' | 'negocio',
  id: string,
): Promise<string | null> {
  try {
    const { data, error } = await supabase
      .from(table)
      .select('imagekit_file_id')
      .eq('id', id)
      .maybeSingle()

    if (error) {
      console.error(
        `[imagekit] Error al leer el archivo anterior de ${table}:`,
        error.message,
      )
      return null
    }

    return data?.imagekit_file_id ?? null
  } catch (error) {
    console.error(
      `[imagekit] Error inesperado al leer el archivo anterior de ${table}:`,
      error,
    )
    return null
  }
}

/**
 * Deletes the file replaced by a new upload.
 * Failures are logged only: the record was already saved.
 */
export async function deleteReplacedImageKitFile(
  previousFileId: string | null,
  nextFileId: string | null,
): Promise<void> {
  if (!previousFileId || previousFileId === nextFileId) return

  try {
    await deleteImageKitFile(previousFileId)
  } catch (error) {
    console.error('[imagekit] No se pudo eliminar el archivo anterior:', error)
  }
}
